package io.knowledgebrain.gateway;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.util.*;
class CourseEnrollmentProxyTest {
 @Test void forwardsOnlySelfVersionAndBodyWithoutCallerPrincipal()throws Exception{var f=new GroupProxyTest();f.init();String path="/api/groups/"+f.id+"/courses/"+f.id+"/enrollment";var r=f.request("PUT",path);r.addHeader("If-Match","\"ce0\"");r.addHeader("X-Principal-Id",f.id);r.addHeader("Authorization","Bearer spoof");r.setContent("{\"state\":\"ENROLLED\"}".getBytes());f.proxy.proxy(r);verify(f.transport).send(eq(new GatewayRoute("collaboration",path)),eq("PUT"),argThat(h->h.get("If-Match").equals(List.of("\"ce0\""))&&!h.containsKey("Authorization")&&!h.containsKey("X-Principal-Id")),any());}
 @Test void enrollmentHistoryAllowsTenButCourseHistoryRemainsFive()throws Exception{var f=new GroupProxyTest();f.init();String base="/api/groups/"+f.id+"/courses/"+f.id;var r=f.request("GET",base+"/enrollment/revisions");r.setQueryString("limit=10");f.proxy.proxy(r);verify(f.transport).send(any(),eq("GET"),any(),any());for(String path:List.of(base+"/enrollment/revisions",base+"/enrollments/"+f.id+"/revisions")){var over=f.request("GET",path);over.setQueryString("limit=11");assertThrows(org.springframework.web.server.ResponseStatusException.class,()->f.proxy.proxy(over));}var course=f.request("GET",base+"/revisions");course.setQueryString("limit=6");assertThrows(org.springframework.web.server.ResponseStatusException.class,()->f.proxy.proxy(course));}
}
